type ClientTrade = Trade & { grossPnl: number; tradingFee: number; swapFee: number };
type CashEvent = { id: number; type: "deposit" | "withdraw" | "initial"; amount: number; note: string; createdAt: string };
type Preset = { id: number; name: string; initialCapital: number; riskPct: number; timezone: string };
type TradeForm = { symbol: string; assetType: AssetType; direction: Direction; entryPrice: string; exitPrice: string; positionSize: string; stopLoss: string; takeProfit: string; riskTradePct: string; setup: string; chartUrl: string; notes: string; tradingFee: string; swapFee: string; openedAt: string; closedAt: string };

